package com.customtexthighlighter;

import java.awt.Color;
import java.util.Locale;

final class ColorParser
{
	private ColorParser()
	{
	}

	static Color parse(String value)
	{
		String colour = value.trim().toLowerCase(Locale.ROOT);
		switch (colour)
		{
			case "red": return Color.RED;
			case "green": return Color.GREEN;
			case "blue": return Color.BLUE;
			case "yellow": return Color.YELLOW;
			case "cyan": return Color.CYAN;
			case "orange": return Color.ORANGE;
			case "pink": return Color.PINK;
			case "purple": return new Color(128, 0, 128);
			case "white": return Color.WHITE;
			case "grey":
			case "gray": return Color.GRAY;
			case "black": return Color.BLACK;
			default: return parseHex(colour);
		}
	}

	private static Color parseHex(String value)
	{
		String hex = value.startsWith("#") ? value.substring(1) : value;
		if (!hex.matches("[0-9a-fA-F]{6}"))
		{
			throw new IllegalArgumentException("Unknown colour. Use a supported colour name or six-digit hex value.");
		}
		return new Color(Integer.parseInt(hex, 16));
	}
}

package com.customtexthighlighter;

import java.awt.Color;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.ColorUtil;

final class HighlightRule
{
	private final String text;
	private final Pattern pattern;
	private final Color colour;

	private HighlightRule(String text, Pattern pattern, Color colour)
	{
		this.text = text;
		this.pattern = pattern;
		this.colour = colour;
	}

	static HighlightRule parse(String ruleText)
	{
		String rule = ruleText.trim();
		String content = rule.substring(1, rule.length() - 1);
		int commaIndex = content.lastIndexOf(',');
		String text = content.substring(0, commaIndex).trim();
		Color colour = ColorParser.parse(content.substring(commaIndex + 1).trim());
		return new HighlightRule(text, Pattern.compile(buildPattern(text),
			Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE | Pattern.UNICODE_CHARACTER_CLASS), colour);
	}

	private static String buildPattern(String text)
	{
		StringBuilder regex = new StringBuilder();
		StringBuilder literal = new StringBuilder();
		for (char character : text.toCharArray())
		{
			switch (character)
			{
				case '*': flushLiteral(regex, literal); regex.append("[\\p{L}\\p{N}_']*"); break;
				case '?': flushLiteral(regex, literal); regex.append('.'); break;
				case '|': flushLiteral(regex, literal); regex.append('|'); break;
				default: literal.append(character);
			}
		}
		flushLiteral(regex, literal);
		return regex.toString();
	}

	private static void flushLiteral(StringBuilder regex, StringBuilder literal)
	{
		if (literal.length() > 0)
		{
			regex.append(Pattern.quote(literal.toString()));
			literal.setLength(0);
		}
	}

	String getText()
	{
		return text;
	}

	String apply(String message)
	{
		Matcher matcher = pattern.matcher(message);
		if (!matcher.find())
		{
			return null;
		}

		matcher.reset();
		StringBuffer result = new StringBuffer();
		while (matcher.find())
		{
			matcher.appendReplacement(result,
				Matcher.quoteReplacement(ColorUtil.wrapWithColorTag(matcher.group(), colour) + "<colNORMAL>"));
		}
		matcher.appendTail(result);
		return result.toString();
	}
}

package com.customtexthighlighter;

import com.google.inject.Provides;
import java.awt.Color;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Custom Text Highlighter",
	description = "Highlights custom text in game messages",
	tags = {"chat", "text", "highlight", "colour", "color", "wildcard"}
)
public class CustomTextHighlighterPlugin extends Plugin
{
	private static final String PREVIEW_PREFIX = "Custom Text Highlighter preview: ";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private CustomTextHighlighterConfig config;

	private List<HighlightRule> rules = Collections.emptyList();

	@Provides
	CustomTextHighlighterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CustomTextHighlighterConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadRules();
	}

	@Override
	protected void shutDown()
	{
		rules = Collections.emptyList();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CustomTextHighlighterConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("rules".equals(event.getKey()))
		{
			loadRules();
			return;
		}

		if ("sendPreview".equals(event.getKey()))
		{
			sendPreviewMessage();
		}
	}

	/*
	 * Lower priority runs later, allowing this plugin to apply its formatting
	 * after most other chat recoloring plugins.
	 */
	@Subscribe(priority = -1000.0f)
	public void onChatMessage(ChatMessage event)
	{
		if (!isEnabledMessageType(event.getType()))
		{
			return;
		}

		MessageNode messageNode = event.getMessageNode();
		if (messageNode == null)
		{
			return;
		}

		String plainMessage = Text.removeTags(event.getMessage());
		if (plainMessage.startsWith(PREVIEW_PREFIX))
		{
			return;
		}

		String highlightedMessage = plainMessage;
		boolean changed = false;
		for (HighlightRule rule : rules)
		{
			String result = rule.apply(highlightedMessage);
			if (result != null)
			{
				highlightedMessage = result;
				changed = true;
			}
		}

		if (changed)
		{
			messageNode.setRuneLiteFormatMessage(highlightedMessage);
			client.refreshChat();
		}
	}

	private boolean isEnabledMessageType(ChatMessageType type)
	{
		switch (type)
		{
			case GAMEMESSAGE:
			case SPAM:
			case ENGINE:
			case MESBOX:
			case LEVELUPMESSAGE:
				return config.highlightGameMessages();
			case PUBLICCHAT:
			case MODCHAT:
				return config.highlightPublicChat();
			case PRIVATECHAT:
			case PRIVATECHATOUT:
			case MODPRIVATECHAT:
				return config.highlightPrivateMessages();
			case CLAN_CHAT:
			case CLAN_GIM_CHAT:
				return config.highlightClanChat();
			case FRIENDSCHAT:
				return config.highlightFriendsChat();
			case CLAN_GUEST_CHAT:
				return config.highlightGuestClanChat();
			case AUTOTYPER:
			case MODAUTOTYPER:
				return config.highlightOtherChat();
			default:
				return false;
		}
	}

	private void sendPreviewMessage()
	{
		clientThread.invokeLater(() ->
		{
			Color previewColour = config.previewColour();
			String previewText = getPreviewText();
			String message = PREVIEW_PREFIX
				+ ColorUtil.wrapWithColorTag(previewText, previewColour)
				+ " [" + toHex(previewColour) + "]";
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
		});
	}

	private String getPreviewText()
	{
		if (!rules.isEmpty())
		{
			return rules.get(0).getText();
		}
		return "Example highlighted text";
	}

	private static String toHex(Color colour)
	{
		return String.format("#%02X%02X%02X", colour.getRed(), colour.getGreen(), colour.getBlue());
	}

	private void loadRules()
	{
		String configuredRules = config.rules();
		if (configuredRules == null || configuredRules.trim().isEmpty())
		{
			rules = Collections.emptyList();
			return;
		}

		List<HighlightRule> parsedRules = new ArrayList<>();
		String[] lines = configuredRules.split("\\R");
		for (int index = 0; index < lines.length; index++)
		{
			String line = lines[index].trim();
			if (line.isEmpty())
			{
				continue;
			}

			try
			{
				parsedRules.add(HighlightRule.parse(line));
			}
			catch (IllegalArgumentException exception)
			{
				log.warn("Ignoring invalid highlight rule on line {}: {} ({})",
					index + 1, line, exception.getMessage());
			}
		}

		rules = Collections.unmodifiableList(parsedRules);
		log.debug("Loaded {} custom text highlight rules", rules.size());
	}
}

package com.customtexthighlighter;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(CustomTextHighlighterConfig.GROUP)
public interface CustomTextHighlighterConfig extends Config
{
	String GROUP = "customtexthighlighter";

	@ConfigSection(
		name = "Chat channels",
		description = "Choose which chat channels can be highlighted",
		position = 3
	)
	String chatChannelsSection = "chatChannels";

	@ConfigItem(
		keyName = "rules",
		name = "Highlight rules",
		description = "Enter one rule per line in the format [text,colour]. Wildcards: * completes the current word, ? matches one character, | matches either option.",
		position = 0
	)
	default String rules()
	{
		return "[Example,#00FF00]";
	}

	@ConfigItem(
		keyName = "previewColour",
		name = "Preview colour",
		description = "Choose the colour used by the preview message",
		position = 1
	)
	default Color previewColour()
	{
		return Color.GREEN;
	}

	@ConfigItem(
		keyName = "sendPreview",
		name = "Send preview message",
		description = "Toggle this setting in either direction to send a preview using the first rule.",
		position = 2
	)
	default boolean sendPreview()
	{
		return false;
	}

	@ConfigItem(
		keyName = "highlightGameMessages",
		name = "Game messages",
		description = "Highlight supported game and system messages",
		section = chatChannelsSection,
		position = 4
	)
	default boolean highlightGameMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightPublicChat",
		name = "Public chat",
		description = "Highlight public chat messages",
		section = chatChannelsSection,
		position = 5
	)
	default boolean highlightPublicChat()
	{
		return false;
	}

	@ConfigItem(
		keyName = "highlightPrivateMessages",
		name = "Private messages",
		description = "Highlight incoming and outgoing private messages",
		section = chatChannelsSection,
		position = 6
	)
	default boolean highlightPrivateMessages()
	{
		return false;
	}

	@ConfigItem(
		keyName = "highlightClanChat",
		name = "Clan chat",
		description = "Highlight clan and group iron chat messages",
		section = chatChannelsSection,
		position = 7
	)
	default boolean highlightClanChat()
	{
		return false;
	}

	@ConfigItem(
		keyName = "highlightFriendsChat",
		name = "Friends chat",
		description = "Highlight friends chat messages",
		section = chatChannelsSection,
		position = 8
	)
	default boolean highlightFriendsChat()
	{
		return false;
	}

	@ConfigItem(
		keyName = "highlightGuestClanChat",
		name = "Guest clan chat",
		description = "Highlight guest clan chat messages",
		section = chatChannelsSection,
		position = 9
	)
	default boolean highlightGuestClanChat()
	{
		return false;
	}

	@ConfigItem(
		keyName = "highlightOtherChat",
		name = "Other chat",
		description = "Highlight supported player chat types not covered above, such as autotyper messages",
		section = chatChannelsSection,
		position = 10
	)
	default boolean highlightOtherChat()
	{
		return false;
	}
}
